REPLACE INTO `settings` (`settingKey`, `settingValue`, `createdAt`, `updatedAt`) VALUES ('about_contact', '{"aboutAm":"አዕማደ ሰላም ሰንበት ትምህርት ቤት በፈለገ ሰላም ቅዱስ ጊዮርጊስ ካቴድራል (ፍኖተ ሰላም፣ ምዕራብ ጎጃም) ስር የሚገኝ መንፈሳዊ ተቋም ሲሆን ወጣቶችንና ምዕመናንን በሃይማኖትና በምግባር ለማነጽ ይሠራል።","aboutEn":"Aemade Selam Sunday School is a spiritual institution under Felegeselam Kidus Giyorgis Cathedral in Finote Selam, West Gojjam, dedicated to edifying youth and parishioners in Orthodox faith and virtuous deeds.","missionAm":"ሕፃናትንና ወጣቶችን በኦርቶዶክሳዊት ተዋሕዶ እምነት ማነጽና ለቤተክርስቲያንና ለአገር የሚጠቅሙ ዜጎች ማድረግ።","missionEn":"Nurturing children and youth in Orthodox Tewahedo faith and shaping productive citizens for Church and society.","visionAm":"በሃይማኖት የጸና፣ በምግባር ያበራና በትምህርት የበለጸገ መንፈሳዊ ትውልድ ማየት።","visionEn":"To see a spiritual generation steadfast in faith, radiant in virtuous deeds, and enriched in divine knowledge.","phone":"","alternatePhone":"","email":"","address":"ፈለገ ሰላም ቅዱስ ጊዮርጊስ ካቴድራል፣ ፍኖተ ሰላም፣ ምዕራብ ጎጃም","mapLink":"","socialLinks":{"telegram":"","youtube":"","facebook":"","tiktok":""},"footerCopyrightAm":"© ፳፻፲፰ አዕማደ ሰላም ሰንበት ትምህርት ቤት። መብቱ በሕግ የተጠበቀ ነው።","footerCopyrightEn":"© 2026 Aemade Selam Sunday School. All rights reserved."}', NOW(), NOW());
REPLACE INTO `settings` (`settingKey`, `settingValue`, `createdAt`, `updatedAt`) VALUES ('contact_details', '{"phone":"","alternatePhone":"","email":"","address":"ፈለገ ሰላም ቅዱስ ጊዮርጊስ ካቴድራል፣ ፍኖተ ሰላም፣ ምዕራብ ጎጃም","poBox":""}', NOW(), NOW());
REPLACE INTO `settings` (`settingKey`, `settingValue`, `createdAt`, `updatedAt`) VALUES ('general', '{"churchNameAm":"የኢትዮጵያ ኦርቶዶክስ ተዋሕዶ ቤተ ክርስቲያን","schoolNameAm":"አዕማደ ሰላም ሰንበት ትምህርት ቤት","mottoAm":"በሃይማኖትና በምግባር የጸና ትውልድ እናፈራለን","contactPhone":"+251911000000","contactEmail":"contact@aemade.org"}', NOW(), NOW());
REPLACE INTO `settings` (`settingKey`, `settingValue`, `createdAt`, `updatedAt`) VALUES ('home_content', '{"heroTitleAm":"አዕማደ ሰላም ሰንበት ትምህርት ቤት ","heroTitleEn":"Welcome to the Sunday School of Felegeselam Kidus Giyorgis Cathedral","heroSubtitleAm":"በኢትዮጵያ ኦርቶዶክስ ተዋሕዶ ቤተክርስቲያን እምነትና ሥርዓትን የሚማሩበትና መንፈሳዊ ሕይወትዎን የሚያዳብሩበት መድረክ","heroSubtitleEn":"A platform to learn the faith and order of the Ethiopian Orthodox Tewahedo Church and cultivate spiritual growth","welcomeMessageAm":"እንኳን ደህና መጡ! በፈለገ ሰላም ቅዱስ ጊዮርጊስ ካቴድራል አዕማደ ሰላም ሰንበት ትምህርት ቤት ተማሪዎችና ምዕመናን አገልግሎት።","welcomeMessageEn":"Welcome to the Sunday School of Felegeselam Kidus Giyorgis Cathedral in Finote Selam, West Gojjam.","primaryCtaTextAm":"የአባላት ምዝገባ","primaryCtaTextEn":"Member Registration","primaryCtaLink":"/register","secondaryCtaTextAm":"ትምህርቶችን ይመልከቱ","secondaryCtaTextEn":"Explore Courses","secondaryCtaLink":"/courses","sections":[{"id":"sinksar","enabled":true,"titleAm":"የዕለቱ ስንክሳር","titleEn":"Today''s Synaxarium","order":1},{"id":"news","enabled":true,"titleAm":"ዜናዎችና ማስታወቂያዎች","titleEn":"News & Announcements","order":2},{"id":"courses","enabled":true,"titleAm":"የሚሰጡ ትምህርቶች","titleEn":"Featured Courses","order":3},{"id":"mezmur","enabled":true,"titleAm":"የምስጋና መዝሙራት","titleEn":"Spiritual Hymns","order":4},{"id":"contact","enabled":true,"titleAm":"አድራሻና ግንኙነት","titleEn":"Contact Us","order":5}],"announcement":{"enabled":false,"textAm":"የዘንድሮው የትምህርት ዘመን ምዝገባ ተጀምሯል!","textEn":"Registration for the new academic year is now open!","type":"info","link":"/register"}}', NOW(), NOW());
